unint32 i;
adcs_vec3_t hs;
int all_ok;
int valid_cfg;

/* 配置合法性检查：required in 4..100, minimum_span finite and > 0, max_rejected_windows <= 1000 */
valid_cfg = (mh_config.required >= 4U) && (mh_config.required <= 100U) &&
            isfinite(mh_config.minimum_span) && (mh_config.minimum_span > 0.0) &&
            (mh_config.max_rejected_windows <= 1000U);

/* Disable clears everything including the rejection counter */
if (!mh_input.enable) {
    mh_state.mode = MH_IDLE;
    mh_state.count = 0U;
    mh_state.rejected = 0U;
    mh_state.minimum = (adcs_vec3_t){0.0, 0.0, 0.0};
    mh_state.maximum = (adcs_vec3_t){0.0, 0.0, 0.0};
    mh_state.bias = (adcs_vec3_t){0.0, 0.0, 0.0};
    mh_output.mode = MH_IDLE;
    mh_output.count = 0U;
    mh_output.rejected = 0U;
    mh_output.bias = (adcs_vec3_t){0.0, 0.0, 0.0};
    mh_output.half_span = (adcs_vec3_t){0.0, 0.0, 0.0};
    mh_output.span_norm = 0.0;
    mh_output.span_energy = 0.0;
    return;
}

/* NULL/nonfinite sample or invalid configuration (including max_rejected_windows) latches FAULT */
if ((!valid_cfg) || (mh_input.sample == NULL) || (!adcs_is_finite_vec3(mh_input.sample))) {
    mh_state.mode = MH_FAULT;
    mh_output.mode = MH_FAULT;
    mh_output.count = mh_state.count;
    mh_output.rejected = mh_state.rejected;
    mh_output.bias = mh_state.bias;
    mh_output.half_span = (adcs_vec3_t){0.0, 0.0, 0.0};
    mh_output.span_norm = 0.0;
    mh_output.span_energy = 0.0;
    return;
}

if (mh_state.mode == MH_FAULT) {
    mh_output.mode = MH_FAULT;
    mh_output.count = mh_state.count;
    mh_output.rejected = mh_state.rejected;
    mh_output.bias = mh_state.bias;
    mh_output.half_span = (adcs_vec3_t){0.0, 0.0, 0.0};
    mh_output.span_norm = 0.0;
    mh_output.span_energy = 0.0;
    return;
}

/* 开始收集：从 IDLE 或 READY 进入 COLLECT 时重置本窗口极值 */
if ((mh_state.mode == MH_IDLE) || (mh_state.mode == MH_READY)) {
    mh_state.mode = MH_COLLECT;
    mh_state.count = 0U;
    mh_state.minimum = *mh_input.sample;
    mh_state.maximum = *mh_input.sample;
}

if (mh_state.mode == MH_COLLECT) {
    if (mh_state.count == 0U) {
        mh_state.minimum = *mh_input.sample;
        mh_state.maximum = *mh_input.sample;
    } else {
        if (mh_input.sample->x < mh_state.minimum.x) mh_state.minimum.x = mh_input.sample->x;
        if (mh_input.sample->x > mh_state.maximum.x) mh_state.maximum.x = mh_input.sample->x;
        if (mh_input.sample->y < mh_state.minimum.y) mh_state.minimum.y = mh_input.sample->y;
        if (mh_input.sample->y > mh_state.maximum.y) mh_state.maximum.y = mh_input.sample->y;
        if (mh_input.sample->z < mh_state.minimum.z) mh_state.minimum.z = mh_input.sample->z;
        if (mh_input.sample->z > mh_state.maximum.z) mh_state.maximum.z = mh_input.sample->z;
    }
    mh_state.count++;
}

/* 每周期先发布当前计数 */
mh_output.count = mh_state.count;
mh_output.rejected = mh_state.rejected;
mh_output.mode = mh_state.mode;

/* 完整窗口判定 */
if ((mh_state.mode == MH_COLLECT) && (mh_state.count >= mh_config.required)) {
    /* bias=(maximum+minimum)/2 */
    mh_state.bias.x = (mh_state.maximum.x + mh_state.minimum.x) / 2.0;
    mh_state.bias.y = (mh_state.maximum.y + mh_state.minimum.y) / 2.0;
    mh_state.bias.z = (mh_state.maximum.z + mh_state.minimum.z) / 2.0;

    /* half_span=(maximum-minimum)/2 */
    hs.x = (mh_state.maximum.x - mh_state.minimum.x) / 2.0;
    hs.y = (mh_state.maximum.y - mh_state.minimum.y) / 2.0;
    hs.z = (mh_state.maximum.z - mh_state.minimum.z) / 2.0;

    /* 逐分量核对 every half_span >= minimum_span */
    all_ok = 1;
    for (i = 0U; i < 3U; i++) {
        double hsv = (i == 0U) ? hs.x : ((i == 1U) ? hs.y : hs.z);
        if (!(hsv >= mh_config.minimum_span)) {
            all_ok = 0;
        }
    }

    /* 发布 bias / half_span / span_norm / span_energy */
    mh_output.bias = mh_state.bias;
    mh_output.half_span = hs;
    mh_output.span_norm = adcs_vec3_norm(&hs);
    mh_output.span_energy = adcs_vec3_dot(&hs, &hs);

    if (all_ok) {
        mh_state.mode = MH_READY;
        mh_output.mode = MH_READY;
    } else {
        /* 已有非零上限且 rejected 已达上限：latch FAULT，不重启 */
        if ((mh_config.max_rejected_windows != 0U) &&
            (mh_state.rejected >= mh_config.max_rejected_windows)) {
            mh_state.mode = MH_FAULT;
            mh_output.mode = MH_FAULT;
        } else {
            /* 否则重启收集并 rejected++（0 表示无上限，但仍计数） */
