    mh_state.mode = MH_FAULT;
    mh_output.mode = mh_state.mode;
    mh_output.count = mh_state.count;
    mh_output.rejected = mh_state.rejected;
    mh_output.bias = mh_state.bias;
    mh_output.half_span = (adcs_vec3_t){0.0, 0.0, 0.0};
    mh_output.span_norm = 0.0;
    mh_output.span_energy = 0.0;
    return;
}

/* --- 3. Disable 清空一切（含 rejected） --- */
if (!mh_input.enable) {
    mh_state.mode = MH_IDLE;
    mh_state.count = 0U;
    mh_state.rejected = 0U;
    mh_state.minimum = (adcs_vec3_t){0.0, 0.0, 0.0};
    mh_state.maximum = (adcs_vec3_t){0.0, 0.0, 0.0};
    mh_state.bias = (adcs_vec3_t){0.0, 0.0, 0.0};
    mh_output.mode = mh_state.mode;
    mh_output.count = mh_state.count;
    mh_output.rejected = mh_state.rejected;
    mh_output.bias = mh_state.bias;
    mh_output.half_span = (adcs_vec3_t){0.0, 0.0, 0.0};
    mh_output.span_norm = 0.0;
    mh_output.span_energy = 0.0;
    return;
}

/* --- 4. 采集：仅当不是 FAULT/READY 时接纳样本 --- */
if ((mh_state.mode != MH_FAULT) && (mh_state.mode != MH_READY)) {
    if (mh_state.count == 0U) {
        mh_state.minimum = *mh_input.sample;
        mh_state.maximum = *mh_input.sample;
    } else {
        if (mh_input.sample->x < mh_state.minimum.x) mh_state.minimum.x = mh_input.sample->x;
        if (mh_input.sample->y < mh_state.minimum.y) mh_state.minimum.y = mh_input.sample->y;
        if (mh_input.sample->z < mh_state.minimum.z) mh_state.minimum.z = mh_input.sample->z;
        if (mh_input.sample->x > mh_state.maximum.x) mh_state.maximum.x = mh_input.sample->x;
        if (mh_input.sample->y > mh_state.maximum.y) mh_state.maximum.y = mh_input.sample->y;
        if (mh_input.sample->z > mh_state.maximum.z) mh_state.maximum.z = mh_input.sample->z;
    }
    mh_state.count++;
    if (mh_state.mode != MH_FAULT && mh_state.mode != MH_READY) {
        mh_state.mode = MH_COLLECT;
    }
}

/* --- 5/6/7. 窗口评估（count>=required 才进入） --- */
if (mh_state.count >= mh_config.required) {
    adcs_vec3_t sum = adcs_vec3_add(&(mh_state.maximum), &(mh_state.minimum));
    adcs_vec3_t diff = adcs_vec3_sub(&(mh_state.maximum), &(mh_state.minimum));
    mh_state.bias = adcs_vec3_scale(&sum, 0.5);
    mh_output.half_span = adcs_vec3_scale(&diff, 0.5);

    mh_output.span_norm = adcs_vec3_norm(&mh_output.half_span);
    mh_output.span_energy = adcs_vec3_dot(&mh_output.half_span, &mh_output.half_span);

    half_x = mh_output.half_span.x;
    half_y = mh_output.half_span.y;
    half_z = mh_output.half_span.z;

    insufficient = 0;
    if (half_x < mh_config.minimum_span) insufficient = 1;
    if (half_y < mh_config.minimum_span) insufficient = 1;
    if (half_z < mh_config.minimum_span) insufficient = 1;

    if (!insufficient) {
        mh_state.mode = MH_READY;
    } else {
        if ((mh_config.max_rejected_windows != 0U) &&
            (mh_state.rejected >= mh_config.max_rejected_windows)) {
            mh_state.mode = MH_FAULT;
        } else {
            mh_state.mode = MH_COLLECT;
            mh_state.count = 0U;
            mh_state.rejected++;
        }
    }
}

/* --- 8. 每次调用末了发布输出 --- */
mh_output.mode = mh_state.mode;
mh_output.count = mh_state.count;
mh_output.rejected = mh_state.rejected;
mh_output.bias = mh_state.bias;
